layer.css:
[data-ryt="footer"] { color: var(--ryt-bg); background-color: var(--ryt-text); font-style: normal; letter-spacing: 0.3px; text-transform: none }
[data-ryt="brand"] { color: #808080; border-radius: 0px; font-family: Helvetica; font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: 0.3px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: transform 0.2s ease-in-out }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: Helvetica; font-size: 14px; font-weight: 700; font-style: normal; line-height: 1.5; letter-spacing: 0.3px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 16px; padding-bottom: 0px; padding-left: 16px; transition: 0.35s; position: relative }
[data-ryt="button"] { color: var(--ryt-bg); background-color: var(--ryt-text); border-top: 1px solid var(--ryt-text); border-right: 1px solid var(--ryt-text); border-bottom: 1px solid var(--ryt-text); border-left: 1px solid var(--ryt-text); border-radius: 0px; font-family: Helvetica; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: 0.3px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 14px; padding-right: 15px; padding-bottom: 14px; padding-left: 15px; transition: border-color 0.35s, color 0.35s, background-color 0.35s }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: Helvetica; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: 0.3px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: Helvetica; font-size: 32px; font-weight: 600; font-style: normal; line-height: normal; letter-spacing: 0.3px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s ease-in-out }
[data-ryt="button"]:hover { color: rgb(44, 79, 74); color: #fff; background-color: #3c6d67; color: var(--ryt-text); background-color: transparent; border-top-color: var(--ryt-text); border-right-color: var(--ryt-text); border-bottom-color: var(--ryt-text); border-left-color: var(--ryt-text); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="nav"] a::after { content: ""; display: block; position: absolute; width: 43.2031px; height: 1px; color: var(--ryt-text); background-color: color-mix(in srgb, var(--ryt-text) 60%, transparent); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: Helvetica; font-size: 14px; font-weight: 700; font-style: normal; line-height: 1.5; letter-spacing: 0.3px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: transform 0.4s cubic-bezier(0.645, 0.045, 0.355, 1), -webkit-transform 0.4s cubic-bezier(0.645, 0.045, 0.355, 1); -webkit-text-fill-color: var(--ryt-text); bottom: 5px; left: 16px }
[data-ryt="nav"] a:hover { color: rgb(44, 79, 74); color: color-mix(in srgb, var(--ryt-text) 80%, transparent); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="brand"]:hover { color: rgb(44, 79, 74); color: var(--ryt-text); transform: scale(1.04); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
